INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (321094, 14405, 'France 24', 'en', 'European drought shrivels crops despite farmers’ best efforts to adapt', 'https://www.france24.com/en/europe/20260813-european-drought-shrivels-crops-despite-farmers-best-efforts-to-adapt', 'The drought roasting much of Europe this summer is taking a heavy toll on crops across the continent, from potatoes in the Netherlands to corn in Bosnia. Triodos, a Dutch bank with a focus on sustainability, has warned that this could reduce gross domestic product across the EU by 1 percent for 2026 – or around €180 billion.', 'https://s.france24.com/media/display/cf090a7a-9731-11f1-9e16-005056bf30b7/w:1024/p:16x9/AP26223531560870.jpg', '2026-08-13T16:47:27+00:00', '2026-08-13T22:50:55.853340'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
