INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329404, 14405, 'The Guardian', 'en', 'How England’s brutal summer heat is affecting farm animals and crops', 'https://www.theguardian.com/environment/2026/aug/14/how-england-summer-heatwave-affecting-farm-animals-crops', 'There are parched fields, overheating sheep and potentially the worst cereal harvest since detailed records began – but it’s a good year for cider apples As parts of the UK swelter through a fifth successive climate crisis-driven heatwave and nearly three-quarters of England remains in drought, how are six homegrown products faring? Continue reading...', 'https://i.guim.co.uk/img/media/8938b01ea471f9c7ca0df5d7f7c96e85e34c5bca/0_0_5325_4262/master/5325.jpg?width=140&quality=85&auto=format&fit=max&s=009b64a453d80606f679098add99e22d', '2026-08-14T14:40:46+00:00', '2026-08-14T14:58:21.832864'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329413, 14405, 'The Guardian', 'en', 'Tougher crops and beaver dams: how UK farmers are tackling drought', 'https://www.theguardian.com/environment/2026/aug/14/crops-beaver-dams-uk-farmers-drought-heatwaves', 'Hit by heatwaves and low rainfall, food producers are finding novel solutions to help crops and cattle survive Ponds and collection tanks, drought-resistant crops and a certain rodent. As the climate crisis brings more extreme weather to Britain, farmers are experimenting with new tactics to tackle drought – and flooding. The string of heatwaves and drought conditions experienced across vast swathes of Britain this summer has brought a series of challenges for food producers, particularly those growing crops more suited to the UK’s traditional climate. Continue reading...', 'https://i.guim.co.uk/img/media/521db8caab17a499ea6e4eee7fcbbe5efcbab898/332_0_3316_2653/master/3316.jpg?width=140&quality=85&auto=format&fit=max&s=6c5f8b8b3905ce9f98d9e3af6358c01f', '2026-08-14T06:00:20+00:00', '2026-08-14T14:58:21.970325'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
