INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (333177, 14422, 'Aaj Tak', 'hi', 'अनुराग ठाकुर की शिकायत पर राहुल को नोटिस, ''अभद्र भाषा'' का आरोप', 'https://www.aajtak.in/india/politics/story/rahul-gandhi-privilege-committee-notice-anurag-thakur-unparliamentary-language-ntc-rlch-dskc-2622162-2026-08-14', 'लोकसभा की विशेषाधिकार समिति ने बीजेपी सांसद अनुराग ठाकुर की शिकायत पर नेता प्रतिपक्ष राहुल गांधी को नोटिस जारी किया है. राहुल गांधी से 28 अगस्त 2026 तक जवाब मांगा गया है. शिकायत में एंटी पेपर लीक बिल पर चर्चा के दौरान असंसदीय और अपमानजनक भाषा के इस्तेमाल और गृह मंत्री पर गंभीर आरोप लगाने का आरोप है.', '', '2026-08-14T14:49:45+00:00', '2026-08-14T17:13:35.165099'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
